import { S3Client } from '@aws-sdk/client-s3';
import { Upload } from '@aws-sdk/lib-storage';

const PART_SIZE = 10 * 1024 * 1024;

// 后端 STS 临时凭据 + 资源寻址契约，字段命名沿用后端 snake_case
export interface TemporaryToken {
  host: string;
  region: string;
  resource_bucket: string;
  resource_uri: string;
  session_token: string;
  sts_ak: string;
  sts_sk: string;
  useAccelerateEndpoint: boolean;
}

export const upload = async (temporaryToken: TemporaryToken,
  blob: Blob) => {
  const upload = new Upload({
    client: new S3Client({
      credentials: {
        accessKeyId: temporaryToken.sts_ak,
        secretAccessKey: temporaryToken.sts_sk,
        sessionToken: temporaryToken.session_token,
      },
      endpoint: temporaryToken.useAccelerateEndpoint ? undefined : `https://${temporaryToken.host}`,
      region: temporaryToken.region,
      useAccelerateEndpoint: temporaryToken.useAccelerateEndpoint,
    }),
    params: {
      Body: blob,
      Bucket: temporaryToken.resource_bucket,
      Key: temporaryToken.resource_uri,
    },
    partSize: PART_SIZE,
  });
  await upload.done();
  return {
    bucket: temporaryToken.resource_bucket,
    key: temporaryToken.resource_uri,
  };
};

export const partUpload = async (
  temporaryToken: TemporaryToken,
  blob: Blob,
  onProgress?: (progress: number) => void,
) => {
  const upload = new Upload({
    client: new S3Client({
      credentials: {
        accessKeyId: temporaryToken.sts_ak,
        secretAccessKey: temporaryToken.sts_sk,
        sessionToken: temporaryToken.session_token,
      },
      endpoint: temporaryToken.useAccelerateEndpoint ? undefined : `https://${temporaryToken.host}`,
      region: temporaryToken.region,
      // 禁用自动校验和计算和验证，避免分段上传时的校验和错误
      requestChecksumCalculation: 'WHEN_REQUIRED',
      responseChecksumValidation: 'WHEN_REQUIRED',
      useAccelerateEndpoint: temporaryToken.useAccelerateEndpoint,
    }),
    params: {
      Body: blob,
      Bucket: temporaryToken.resource_bucket,
      Key: temporaryToken.resource_uri,
    },
    partSize: PART_SIZE,
  });

  // 监听上传进度
  if (onProgress) {
    upload.on('httpUploadProgress', (progress) => {
      if (progress.loaded && progress.total) {
        const percent = (progress.loaded / progress.total) * 100;
        onProgress(percent);
      }
    });
  }

  await upload.done();
  return {
    bucket: temporaryToken.resource_bucket,
    key: temporaryToken.resource_uri,
  };
};
